// ─────────────────────────────────────────────────────────────────────────
//  05 · weighted allocation                                    ★★★ stretch
//  concepts: largest remainder · proportional allocation
// ─────────────────────────────────────────────────────────────────────────
//
//  Allocate a discount across order lines in proportion to their weights.
//  Floor every share, then hand leftover cents to the largest remainders.

using static Bootcamp.Check;

List<long> AllocateByWeights(long totalCents, List<int> weights)
{
    long sumW = weights.Sum(w => (long)w);
    var shares = weights.Select(w => totalCents * w / sumW).ToList();
    long left = totalCents - shares.Sum();
    var byRemainder = Enumerable.Range(0, weights.Count)
        .OrderByDescending(i => totalCents * weights[i] % sumW)
        .ThenBy(i => i)
        .ToList();
    for (int k = 0; k < left; k++)
        shares[byRemainder[k]]++;
    return shares;
}

// ──────────────────────────── tests ──────────────────────────────────────

Test("(100, [1,1,1]) -> [34, 33, 33] (equal remainders: earlier index)", () =>
    Eq(AllocateByWeights(100, [1, 1, 1]), new long[] { 34, 33, 33 }));

Test("(101, [2,1]) -> [67, 34] (the .67 remainder beats .33)", () =>
    Eq(AllocateByWeights(101, [2, 1]), new long[] { 67, 34 }));

Test("(100, [50,50]) -> [50, 50] (boundary: exact)", () =>
    Eq(AllocateByWeights(100, [50, 50]), new long[] { 50, 50 }));

Test("(1000, [3,2,5]) -> [300, 200, 500] (exact)", () =>
    Eq(AllocateByWeights(1000, [3, 2, 5]), new long[] { 300, 200, 500 }));

Test("(10, [1,1,1]) -> [4, 3, 3]", () =>
    Eq(AllocateByWeights(10, [1, 1, 1]), new long[] { 4, 3, 3 }));

