// ─────────────────────────────────────────────────────────────────────────
//  07 · strict money parse                                     ★★☆ core
//  concepts: NumberStyles · input validation
// ─────────────────────────────────────────────────────────────────────────
//
//  `NumberStyles.Number` treats commas as thousands separators ANYWHERE.
//  A German user typing "12,34" (12.34) is charged 1234.

using System.Globalization;
using static Bootcamp.Check;

decimal? ParseLoose(string s)
{
    return decimal.TryParse(s, NumberStyles.Number, CultureInfo.InvariantCulture, out var d) ? d : null;
}

decimal? ParseStrict(string s)
{
    return decimal.TryParse(s, NumberStyles.AllowDecimalPoint | NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out var d) ? d : null;
}

// ──────────────────────────── tests ──────────────────────────────────────

